Giả sử đầu vào là 2 3 4 5 0. Đầu ra của đoạn mã sau là gì?

#include <iostream>
using namespace std;

int main()
{
  int number, max;
  cin >> number;
  max = number;

  while (number != 0)
  {
    cin >> number;
    if (number > max)
      max = number;
  }

  cout << "max is " << max << endl;
  cout << "number " << number << endl;

  return 0;
}

